// Lee la cotización que devolvió la caja (una línea JSON) y decide cómo sigue.
const E = ($('Entradas (canal, capítulo, modo)').isExecuted ? $('Entradas (canal, capítulo, modo)').first().json : Object.fromEntries($('Entradas (canal, capítulo, modo)').params.assignments.assignments.filter(a => !String(a.value).startsWith('=')).map(a => [a.name, a.value])));
const modo = String(E.modo || 'cotizar').trim().toLowerCase();
if (!['cotizar', 'pagar'].includes(modo)) throw new Error('En «Entradas» modo debe ser "cotizar" o "pagar" (vino: ' + E.modo + ')');
// PAGAR_PASOS (inmi 2-nov-2026): pago preaprobado por paso, con tope duro total. Genérico: cualquier canal/capítulo.
// «pagar_pasos» = lista de pasos (p. ej. "4,4p"); «tope_pasos_usd» = tope total de esos pasos en esta corrida. Además el servidor exige
// cajas/HABILITAR_PAGO_00 (monto, desde, pasos) y el VER⇢ seco antes de llamar.
const PID = '4';
const LISTA = String(E.pagar_pasos || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const POR_LISTA = LISTA.includes(PID);
const TOPE_P = Number(E.tope_pasos_usd || 0);
const GASTADO_P = ["4 · leer resultado", "4p · leer resultado", "5 · leer resultado"].reduce((s, n) => { try { return s + ($(n).isExecuted ? $(n).all().reduce((t, x) => t + Number(x.json.usd_real_total || 0), 0) : 0); } catch (e) { return s; } }, 0);
const out = [];
for (const it of $input.all()) {
  const txt = String(it.json.stdout || '').trim().split('\n').pop();
  let r;
  try { r = JSON.parse(txt); } catch (e) { throw new Error('La caja 4 no devolvió JSON. stdout: ' + String(it.json.stdout || '').slice(0, 300) + ' | stderr: ' + String(it.json.stderr || '').slice(0, 300)); }
  if (!r.ok) throw new Error('Caja 4: ' + r.error);
  const pendientes = r.pasos.filter(p => !p.ya_hecho);
  let ruta = 'seguir';
  if (r.repetido_en_esta_corrida) ruta = 'repetido';
  else if (POR_LISTA && pendientes.length) {
    const ap = Math.round(pendientes.reduce((s, p) => s + p.peor_caso_usd, 0) * 10000) / 10000;
    if (!r.todo_cabe) throw new Error('Caja 4: el precio pasa el tope por llamada (US$ ' + r.tope_por_llamada_usd + '). No se llama.');
    if (!(TOPE_P > 0)) throw new Error('pagar_pasos incluye 4 pero tope_pasos_usd no es mayor que 0. No se llama.');
    if (ap > TOPE_P - GASTADO_P + 1e-9) throw new Error('Caja 4: peor caso US$ ' + ap + ' no cabe en lo que queda del tope (US$ ' + Math.round((TOPE_P - GASTADO_P) * 10000) / 10000 + ' de ' + TOPE_P + '). No se llama.');
    ruta = 'preaprobado';
  }
  else if (modo === 'pagar' && pendientes.length) {
    if (!r.todo_cabe) throw new Error('Caja 4: el precio pasa el tope por llamada (US$ ' + r.tope_por_llamada_usd + '). No se llama.');
    ruta = 'aprobar';
  }
  const a_pagar = Math.round(pendientes.reduce((s, p) => s + p.peor_caso_usd, 0) * 10000) / 10000;
  const lineas = r.pasos.map(p => '• ' + p.paso + ': ' + (p.ya_hecho ? 'ya hecho (US$ ' + p.usd_real_anterior + ' real), no se repite' : 'hasta US$ ' + p.peor_caso_usd + (p.aproximado_sin_base ? ' (aprox., aún no hay base)' : '')));
  r.modo = modo; r.ruta = ruta; r.a_pagar_peor_caso_usd = a_pagar;
  r.resumen = 'Canal ' + r.canal + ' · capítulo ' + r.capitulo + ' «' + r.titulo + '» (' + r.episodio + ')\n' + lineas.join('\n') +
    '\nTOTAL a pagar (peor caso): US$ ' + a_pagar + ' · tope por llamada US$ ' + r.tope_por_llamada_usd + ' · modelo ' + r.modelo +
    '\nUn intento por pedido, queda en el ledger antes de llamar. Lo real suele salir bastante menos (prueba: base 0.27, 2a 0.20, 2b 0.32, 2c 0.57).';
  out.push({ json: r });
}
return out;

