  if (!r.ok) throw new Error('Caja 4a: ' + r.error);
  if (r.llama_a_pago) throw new Error('Caja 4a: no debía llamar a un servicio pago');
  out.push({ json: { caja: '4a', resumen: r.espera_4p ? ('esperando a 4p: ' + r.mensaje) : r.resumen, ...r } });
}
return out;

// Lee la respuesta de la caja 4a2 (una línea JSON). GRATIS: Blender corre en el servidor taller (213), nunca llama a un servicio pago.
const out = [];
for (const it of $input.all()) {
  const txt = String(it.json.stdout || '').trim().split('\n').pop();
  let r;
  try { r = JSON.parse(txt); } catch (e) { throw new Error('La caja 4a2 no devolvió JSON. stdout: ' + String(it.json.stdout || '').slice(0, 300) + ' | stderr: ' + String(it.json.stderr || '').slice(0, 300)); }
  if (!r.ok) throw new Error('Caja 4a2: ' + r.error);
  if (r.llama_a_pago) throw new Error('Caja 4a2: no debía llamar a un servicio pago');
  // orden 60 + 61/61b: detalle por escenario = molde de Blender + conteo del ambiente vivo (zona AMBIENTE de 4a1)
  const AMB = r.ambiente_por_escenario || {};
  const amb = (id) => { const c = AMB[id]; if (!c) return 'ambiente: sin datos'; const t = Object.values(c).reduce((a, b) => a + (Number(b) || 0), 0);
    return `ambiente ${t} (` + Object.entries(c).filter(([k, v]) => v).map(([k, v]) => `${k} ${v}`).join(', ') + ')'; };
  const ids = [...new Set([...(r.moldes || []).map(m => m.id), ...Object.keys(AMB)])];
  const M = Object.fromEntries((r.moldes || []).map(m => [m.id, m]));
  const por_escenario = ids.map(id => { const m = M[id];
    const mol = !m ? 'sin molde' : (m.ok === false ? ('FALLÓ: ' + (m.error || '')) : `${m.segundos} s · ${m.renders} renders · ${m.avisos} avisos${m.reutilizado ? ' (reutilizado)' : ''}`);
    return `${id}: ${mol} · ${amb(id)}`; });
  const vacios = r.ambiente_vacios || [];
  const resumen = (r.espera_4p ? ('esperando a 4p: ' + r.mensaje) : r.resumen) + (vacios.length ? ` · AMBIENTE VACÍO en: ${vacios.join(', ')}` : '') + ((r.ambiente_ascensos || []).length ? ` · ascensos a oficial: ${r.ambiente_ascensos.length}` : '');
  out.push({ json: { caja: '4a2', ...r, resumen, por_escenario } });
}
return out;

// Lee la respuesta de la caja 4a3 (una línea JSON). GRATIS: solo arma la galería con los renders de Blender (4a2).
const out = [];
for (const it of $input.all()) {
  const txt = String(it.json.stdout || '').trim().split('\n').pop();
  let r;
  try { r = JSON.parse(txt); } catch (e) { throw new Error('La caja 4a3 no devolvió JSON. stdout: ' + String(it.json.stdout || '').slice(0, 300) + ' | stderr: ' + String(it.json.stderr || '').slice(0, 300)); }
  if (!r.ok) throw new Error('Caja 4a3: ' + r.error);
  if (r.llama_a_pago) throw new Error('Caja 4a3: no debía llamar a un servicio pago');
  const extra = (r.escenarios_con_molde !== undefined) ? ` · con molde: ${r.escenarios_con_molde} · sin molde: ${(r.sin_molde || []).length}` : '';
  // orden 60 + 61/61b: detalle por escenario (con/sin molde y, si la caja lo trae, el ambiente vivo)
  const AMB = r.ambiente_por_escenario || {};
  const sin = new Set(r.sin_molde || []);
  const ids = [...new Set([...Object.keys(AMB), ...(r.sin_molde || [])])];
  const por_escenario = ids.map(id => { const c = AMB[id]; const t = c ? Object.values(c).reduce((a, b) => a + (Number(b) || 0), 0) : null;
    return `${id}: ${sin.has(id) ? 'sin molde' : 'con molde'}` + (c ? ` · ambiente ${t} (` + Object.entries(c).filter(([k, v]) => v).map(([k, v]) => `${k} ${v}`).join(', ') + ')' : ''); });
  out.push({ json: { caja: '4a3', ...r, resumen: (r.espera_4p ? ('esperando a 4p: ' + r.mensaje) : r.resumen) + extra, por_escenario } });
}
return out;

// 4a4 · Prompts de escenario (orden 59): 1 prompt BASE por escenario (con molde de Blender) + 1 prompt de EDICIÓN de la base por variante.
// SOLO COTIZAR: esta caja NO llama a Argon aunque el modo sea «pagar» (además el servidor lo bloquea sin HABILITAR_PAGO_4A4).
// PISTA INMI (2026-10-29): orden 68 — un pedido por escenario; «hecho» = JSON válido (o «reparado» con OK). Muestra lo que falta pedir,
// lo que se puede reparar GRATIS y, si hubo corrida, los intentos (429 = no cobrado) y el posible cobro de errores.
// PISTA INMI (2026-10-29): orden 69 — UNA imagen por cámara del molde (base + una vista por cada otra cámara). El CÓDIGO lo revisa:
// si falta o se repite una cámara, el escenario queda INCOMPLETO (no cuenta como hecho) y aquí se dice qué cámaras faltan.
const out = [];
const usd = v => Math.round((Number(v) || 0) * 10000) / 10000;
for (const it of $input.all()) {
  const txt = String(it.json.stdout || '').trim().split('\n').pop();
  let r;
  try { r = JSON.parse(txt); } catch (e) { throw new Error('La caja 4a4 no devolvió JSON. stdout: ' + String(it.json.stdout || '').slice(0, 300) + ' | stderr: ' + String(it.json.stderr || '').slice(0, 300)); }
  if (!r.ok && !r.resultados) throw new Error('Caja 4a4: ' + r.error);
  const pasos = r.pasos || [];
  const pend = pasos.filter(p => !p.ya_hecho);
  const total = usd(pend.reduce((s, p) => s + (Number(p.peor_caso_usd) || 0), 0));
  const vistos = new Set();
  const lineas = [];
  for (const p of pasos) {
    if (p.ya_hecho) {
      const k = (p.cubre_desde || p.paso);
      lineas.push('• ' + (p.ids || []).join(', ') + ': ya válido (' + k + (vistos.has(k) ? '' : ', US$ ' + p.usd_real_anterior + ' real') + ')');
      vistos.add(k);
    } else {
      const ia = p.incompleto_antes;
      lineas.push('• ' + (p.ids || []).join(', ') + (ia ? ': INCOMPLETO → se vuelve a pedir (' + String(ia.texto || '').replace(/^[^:]*: INCOMPLETO — /, '') + ')' : ': FALTA') + ' · hasta US$ ' + p.peor_caso_usd + (p.max_out ? ' · salida ' + p.max_out : '') + (p.cabe_en_tope ? '' : ' (NO cabe en el tope)'));
    }
  }
  const rep = r.reparables_gratis || [];
  const lrep = rep.map(z => '• ' + z.paso + ': JSON roto, se arregla GRATIS (' + (z.arreglos || []).length + ' arreglo/s) → recupera ' + (z.escenarios_recuperados || []).join(', ') +
    (z.camaras ? ' · cámaras: ' + Object.entries(z.camaras).map(([k, v]) => v === 'completo' ? k + ' completo' : String(v)).join('; ') : '') +
    (z.archivo_reparado_escrito ? ' · archivo .reparado.json ya escrito' : '') + ' · para usarlo (US$ 0, con OK de Ricardo): ' + z.aplicar);
  const cubre = new Set(rep.flatMap(z => z.escenarios_completos || z.escenarios_recuperados || []));   // orden 69: solo lo que trae TODAS sus cámaras
  const falta = r.falta_pedir || pend.flatMap(p => p.ids || []);
  const ahorro = falta.length && falta.every(i => cubre.has(i)) ? ('\nSi se aplica el arreglo gratis, NO hace falta pagar estos US$ ' + total + '.') : '';
  // corrida (correr): estado por pedido, intentos y posible cobro
