}
if (!r.ok) return [{ json: { caja: 'ver', ok: false, aviso: 'No se pudieron leer las imágenes (no es grave, el flujo sigue): ' + r.error } }];
if (!r.imagenes || !r.imagenes.length) return [{ json: { caja: 'ver', ok: true, que: r.que, aviso: 'Todavía no hay imágenes. ' + (r.aviso || ''), resumen: r.resumen } }];
const grupos = {};
for (const im of r.imagenes) (grupos[im.escenario] = grupos[im.escenario] || []).push(im);
const out = [];
for (const [eid, ims] of Object.entries(grupos)) {
  const binary = {}, lista = [];
  ims.forEach((im, i) => {
    let k = String(im.archivo).replace(/\.[a-z]+$/, '').replace(eid + '__', '').replace(/[^A-Za-z0-9_@-]/g, '_') || ('img' + i);
    if (k === eid.replace(/[^A-Za-z0-9_@-]/g, '_')) k = 'base';
    if (binary[k]) k = k + '_' + i;
    binary[k] = { data: im.b64, mimeType: im.mime, fileName: im.archivo, fileExtension: String(im.archivo).split('.').pop() };
    lista.push({ binario: k, tipo: im.tipo, que_es: im.nombre, tamano: im.ancho + '×' + im.alto, original: im.ancho_original + '×' + im.alto_original, en_servidor: im.ruta });
  });
  out.push({ json: { caja: 'ver', que: r.que, escenario: eid, nombre: ims[0].escenario_nombre, imagenes: lista.length, lista, resumen_total: r.resumen, carpeta: r.carpeta }, binary });
}
