  out.push({ json: { caja: '4a0', ok: true, resumen: '«' + e.nombre + '»: ' + (e.decision === 'reutilizar' ? 'es el mismo lugar que ' + e.biblioteca_id + ' → se reutiliza (US$0 en 4a1)' : 'es otro lugar → se investiga como nuevo') + ' · faltan por confirmar: ' + ((r.resumen || {}).confirmar || 0), ...r } });
