  const res = r.resultados || [];
  const c = (k) => res.filter(x => x.ok && x.como === k).map(x => x.escenario_id);
  const mal = res.filter(x => !x.ok).map(x => (x.id_en_capitulo || x.escenario_id || '?') + ': ' + x.error);
  const inc = res.filter(x => x.ok && x.completo === false).map(x => x.escenario_id + ' (falta: ' + (x.faltan || []).join(', ') + ')');
  const resumen = 'Biblioteca · nuevos: ' + (c('nuevo').join(', ') || '—') + ' · reutilizados: ' + (c('reutilizado').join(', ') || '—') +
    ' · ya estaban: ' + (c('ya_guardado').join(', ') || '—') + (inc.length ? '\nGuardados incompletos: ' + inc.join('; ') : '') + (mal.length ? '\nNO guardados: ' + mal.join('; ') : '');
  if (!r.ok && !res.length) throw new Error('Caja 4a7: ' + r.error);
  if (mal.length) throw new Error(resumen);
  out.push({ json: { caja: '4a7', resumen, ...r } });
}
return out;

