function peorUsd(j){
  if(j.a_pagar_peor_caso_usd!=null && j.a_pagar_peor_caso_usd!=='') return Number(j.a_pagar_peor_caso_usd);
  if(j.usd_peor_caso_total!=null && j.usd_peor_caso_total!=='') return Number(j.usd_peor_caso_total);
  const pe=j.por_escena||{};
  const cap=j.capitulo_estimado||{};
  let esc=0;
  const vals=Object.values(pe);
  if(vals.length){
    esc=vals.reduce((s,row)=>s+Number((row&&(row.total_peor_usd??row.sin_reparar_usd))||0),0);
  } else {
    esc=Number(cap.total_peor_usd||0);
  }
  const e1=Number(j.etapa1_solo_pedidas_usd ?? j.etapa1_usd ?? 0);
  const n=e1+esc;
  return Number.isFinite(n) ? Math.round(n*10000)/10000 : null;
}

