// 0 crear PJ + 1 capturar/describir voz · UNIVERSAL (inmi 2-nov-2026): datos del formulario «Cargar personajes» o de la
// entrada (pj_id/nombre, canal, descripcion, imagenes, voz_captura). SIN ejemplo fijo: si no llega nada, FALLA claro.
// Altura NO se toma del formulario: solo Blender.
const sel=(n)=>{try{const x=$(n); if(x.isExecuted===false) return null; const a=x.all(); return a&&a.length?a:null;}catch(e){return null;}};
const slug=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9_-]+/g,'_').replace(/^[_-]+|[_-]+$/g,'').slice(0,80);
const f=((sel('Cargar personajes · formulario')||[])[0]||{}).json||null;
const inp=(($input.all()[0])||{}).json||{};
const src=(inp.pj_id||inp.nombre||inp.personaje)?inp:(f||{});
const tomar=(o,re)=>{const k=Object.keys(o||{}).find(k=>re.test(k)); return k===undefined?'':String(o[k]==null?'':o[k]).trim();};
const nombre=String(src.nombre||tomar(src,/^personaje/i)||'').trim();
const version=String(src.version||tomar(src,/^versi/i)||'').trim();
const canal=String(src.canal||tomar(src,/^canal/i)||'').trim()||null;
if(!nombre&&!src.pj_id) throw new Error('crear PJ: no llegaron datos del personaje (formulario «Cargar personajes» o entrada con pj_id/nombre). No hay ejemplo fijo.');
const pj_id=slug(src.pj_id||(nombre+(version?'_'+version:'')));
const adn_personaje={descripcion_visual:src.descripcion||tomar(src,/^descrip/i)||null, nunca_cambia:src.nunca_cambia||tomar(src,/nunca cambia/i)||null,
  vestuario:src.vestuario||null, version:version||null, altura_m:null};
return [{json:{pj_id, nombre:nombre||pj_id, canal, adn_personaje, imagenes:Array.isArray(src.imagenes)?src.imagenes:[],
  voz_captura:src.voz_captura||null, escena:src.escena||null, origen:src===inp?'entrada':'formulario Cargar personajes'}}];

