// Sellar FIJO en perfil PJ (stub: hash djb2, no escribe disco). Perfil universal: canal + imágenes + ADN + voz_adn.
function h(s){let x=5381;for(const c of s)x=((x<<5)+x+c.charCodeAt(0))>>>0;return x.toString(16);}
return $input.all().map(it=>{const p=it.json;
  const base={adn_personaje:p.adn_personaje,voz_adn:p.voz_adn};
  const hash=h(JSON.stringify(base));
