  const gap = x => `[GAP ${x}]`;
  const nom = f => String((f && (f.nombre || f.id)) || '?').toUpperCase();
  const adn = f => (f && f.adn_ako && f.adn_ako.texto) ? f.adn_ako.texto : gap('ADN ' + (f ? f.id : '?') + ': ' + ((f && f.motivo) || 'sin ADN Ako en disco'));
