  const hojas = imgs.slice(2, -1).map((im, k) => `Imagen ${k + 3} = ${im.rol}${im.hoja_sola ? ' (hoja sola)' : ''}: ${im.ref || gap('hoja ' + im.id)}`).join('\n');
  const ov = d.overrides || {}; const prohib = [...(ov.prohibiciones || []), ...(ov.reglas || [])];
  const ctxt = x => x == null || x === '' ? null : (typeof x === 'string' ? x : JSON.stringify(x));
  const V = {
    '[FONDO_REF]': t.fondo_ref || gap('fondo_ref'), '[MOLDE_REF]': t.molde_ref || gap('molde_ref'),
    '[HOJAS_LISTA]': hojas || gap('hojas'), '[ESTILO_REF]': imgs[imgs.length - 1].ref || gap('estilo_ref'),
    '[ADN_ESCENARIO]': esc ? adn(esc) : gap('escenario: la toma no trae escenario'),
    '[ADN_ESTILO]': est ? adn(est) : gap('estilo del canal'),
    '{ADN_PERSONAJES_LISTA}': pjs.length ? pjs.map(f => `### ADN ${nom(f)} (FIJO)\n${adn(f)}`).join('\n\n') : gap('casting: la toma no trae personajes'),
    '[N]': String(pjs.length), '[NOMBRES]': pjs.map(nom).join(' + ') || gap('nombres'),
    '{ADN_OBJETOS_LISTA}': objs.length ? objs.map(f => `### ADN ${nom(f)} (FIJO${f.dueno ? ' · de ' + String(f.dueno).toUpperCase() : ''}${f.hoja_sola ? ' · hoja sola' : ''})\n${adn(f)}`).join('\n\n') : 'ninguno',
    '[ADN_PROPS_EXTRA]': ctxt(p.props_extra) || 'ninguno',
    '[BLOQUE_ACCION_MOLDE]': (p.variable_accion || '').trim() || gap('VARIABLE_ACCIÓN: correr Maestro acción v2 (01_MAESTRO_ACCION_v2) antes de pintar'),
    '[GUION_PEDAZO]': ctxt(p.guion) || gap('guion'), '[PLAN_TOMA]': ctxt(p.plan) || gap('plan toma'), '[SCAN_UTIL]': ctxt(p.scan) || gap('scan %'),
    '{PROHIBICIONES_CANAL_ESCENA}': prohib.join(' · '),
  };
  let prompt = String(d.plantilla_director || '');
  for (const [k, v] of Object.entries(V)) prompt = prompt.split(k).join(v);
  prompt = prompt.replace(/ · {2,}· /g, ' · ').replace(/ ·  · /g, ' · ').replace('Sin texto en imagen ·  · ', 'Sin texto en imagen · ').trim();
  out.push({ json: { prompt_director: prompt, imagenes_orden: imgs, ok: true,
