function idsDe(nombre){
  try{
    if(!$(nombre).isExecuted) return [];
    const acc=[];
    for(const it of $(nombre).all()){
      const j=it.json||{};
      if(Array.isArray(j.job_ids)) acc.push(...j.job_ids);
      if(j.job_id) acc.push(j.job_id);
    }
    return acc;
  }catch(e){return [];}
}
const raw=[].concat(
  idsDe('FAB · leer encolado personaje'),
  idsDe('FAB · leer encolado escenario'),
  idsDe('FAB · leer encolado objeto'),
  idsDe('FAB · leer encolado objeto del personaje')
);
const job_ids=[...new Set(raw.filter(x=>typeof x==='string' && /^[a-f0-9]{16}$/.test(x)))];
return [{json:{ok:true, job_ids, n:job_ids.length, comando: job_ids.length?('fabrica_estado '+job_ids.join(',')):null, gasto_usd:0}}];

