function entrada(){const n=$('Entradas (canal, capítulo, modo)');return n.isExecuted?n.first().json:Object.fromEntries(n.params.assignments.assignments.filter(a=>!String(a.value).startsWith('=')).map(a=>[a.name,a.value]));}
function parseNodo(nombre){
  try{
    if(!$(nombre).isExecuted) return null;
    const it=$(nombre).first().json||{};
    if(Array.isArray(it.detalle_escenas)&&it.detalle_escenas.length) return it;
    if(Array.isArray(it.lista_escenas)&&it.lista_escenas.length) return it;
    if(it.stdout){ try{return JSON.parse(String(it.stdout).trim().split('\n').pop());}catch(e){return it;} }
    return it;
  }catch(e){return null;}
}
const E=entrada();
const fuentes=['01 · P1 ¿dirigir? (cotización exacta)','01 · cotizar dirección (gratis)','01 · leer'];
let lista=[]; let detalle=[]; let origen=null;
for(const n of fuentes){
  const r=parseNodo(n); if(!r) continue;
  const arr=r.detalle_escenas||r.lista_escenas||r.escenas||[];
  const nums=[];
  if(Array.isArray(arr)){
    for(const e of arr){
      if(e==null) continue;
      if(typeof e==='number'||typeof e==='string') nums.push(String(e));
      else if(typeof e==='object' && (e.escena!=null||e.id!=null||e.n!=null)) nums.push(String(e.escena!=null?e.escena:(e.id||e.n)));
    }
  } else if(arr && typeof arr==='object'){
    Object.keys(arr).forEach(k=>nums.push(String(k)));
  }
  if(nums.length){ lista=nums; detalle=Array.isArray(arr)?arr:[]; origen=n; break; }
}
const vistos=new Set();
lista=lista.map(s=>String(s).trim()).filter(s=>s&&!vistos.has(s)&&vistos.add(s));
lista.sort((a,b)=> (Number(a)||0)-(Number(b)||0) || a.localeCompare(b));
const pedida=String(E.escena||'').trim();
if(pedida){
  if(!lista.includes(pedida)) return [{json:{ok:false, error:'La escena '+pedida+' no está en la lista del 01 (no se inventa)', canal:E.canal, capitulo:E.capitulo, escena:pedida, lista_01:lista, pendientes:[], total:0}}];
  lista=[pedida];
}
if(!lista.length) return [{json:{ok:false, error:'El 01 no devolvió la lista de escenas del capítulo (no se inventa)', canal:E.canal, capitulo:E.capitulo, pendientes:[], total:0}}];
const _bucle={pendientes:lista.slice(), hechos:[], fallidos:[], resultados:[], indice:0, total:lista.length, origen};
return [{json:{ok:true, canal:E.canal, capitulo:E.capitulo, modo:E.modo, tope_usd:E.tope_usd, total:lista.length, lista_escenas:lista, detalle_escenas:detalle, _bucle, origen}}];

const prev=$input.first().json||{};
const b=JSON.parse(JSON.stringify(prev._bucle||{pendientes:[],hechos:[],fallidos:[],resultados:[],indice:0,total:0}));
if(!b.pendientes.length) return [{json:{...prev, _bucle:b, quedan:false}}];
const escena=String(b.pendientes[0]);
const _reintento = b._reintento_de===escena;
if(_reintento) delete b._reintento_de;
return [{json:{...prev, escena, quedan:true, _bucle:b, etapa:'sb', _reintento}}];

function entrada(){const n=$('Entradas (canal, capítulo, modo)');return n.isExecuted?n.first().json:Object.fromEntries(n.params.assignments.assignments.filter(a=>!String(a.value).startsWith('=')).map(a=>[a.name,a.value]));}
const E=entrada();
let t={}; try{ if($('CAP · tomar siguiente escena').isExecuted) t=$('CAP · tomar siguiente escena').first().json||{}; }catch(e){}
const inp=$input.first().json||{};
const b=JSON.parse(JSON.stringify((t._bucle||inp._bucle||{pendientes:[],hechos:[],fallidos:[],resultados:[],indice:0,total:0})));
const escena=String(t.escena||inp.escena||'');
const videos=[];
for (const k of ['videos','archivos','mp4','salidas']){
  const v=inp[k];
  if(Array.isArray(v)) v.forEach(x=>{ if(typeof x==='string'&&x.endsWith('.mp4')) videos.push(x); else if(x&&x.ruta) videos.push(x.ruta); else if(x&&x.video) videos.push(x.video); });
  else if(typeof v==='string'&&v.endsWith('.mp4')) videos.push(v);
}
if(inp.video && String(inp.video).endsWith('.mp4')) videos.push(inp.video);
if(inp.salida && String(inp.salida).endsWith('.mp4')) videos.push(inp.salida);

// ¿llegamos aquí porque no hay storyboard en disco?
let cotizo_ok=false;
try{ if($('SB · leer cotización').isExecuted){ const q=$('SB · leer cotización').first().json||{}; cotizo_ok=q.ok===true; } }catch(e){}
const sin_sb = (inp.ok===false && (inp.etapa==='sb' || !inp.videos) && cotizo_ok && !videos.length && !inp.omitido_gpu);

let estado='ok';
let motivo=inp.error||inp.aviso||inp.fab_nota||null;
const estMotor=String(inp.estado||'');
const gpu=inp.gpu||{};
const falloMotor=/^(FALLO_|STOP_|ERROR)/i.test(estMotor) || gpu.ok===false || inp.revision_ok===false;
if(sin_sb || inp.cotizado_sin_sb){ estado='cotizado_sin_storyboard'; motivo=motivo||'cotizado; no hay storyboard en disco y en cotizar no se genera'; }
else if(falloMotor){ estado='fallo'; motivo=motivo||gpu.error||estMotor||'fallo del motor'; }
else if(inp.ok===false || inp.error){ estado='fallo'; }
else if(inp.omitido_gpu){ estado='preparado_sin_gpu'; }
else if(videos.length){ estado='filmado'; }
else if(inp.ok===true){ estado='ok'; }

const rec={escena, estado, ok: estado!=='fallo', etapa:inp.etapa||null, videos:[...new Set(videos)], motivo, reintento:!!t._reintento, usd:Number(inp.usd_gastado||inp.gasto_usd||0), estado_motor:estMotor||null};
b.pendientes=(b.pendientes||[]).filter(e=>String(e)!==escena);
// Un reintento del bucle solo si el fallo no vino del motor (FALLO_GPU ya reintenta capacidad adentro; no se vuelve a pagar SB).
if(estado==='fallo' && !rec.reintento && !falloMotor){
  b.pendientes.unshift(escena);
  rec.reintento_programado=true;
  b._reintento_de=escena;
} else if(estado==='fallo'){
  b.fallidos.push(rec);
} else {
  b.hechos.push(rec);
}
// si reintentamos, la siguiente toma debe saberlo
if(rec.reintento_programado){ /* se marca al tomar */ }
b.resultados.push(rec);
b.indice=(b.indice||0)+1;
return [{json:{ok:true, canal:E.canal, capitulo:E.capitulo, modo:E.modo, tope_usd:E.tope_usd, _bucle:b, quedan:b.pendientes.length>0, total:b.total, hechas:b.hechos.length, fallidas:b.fallidos.length}}];

